import json
from pathlib import Path
root = Path('/app/release')
findings = json.loads((root / 'scanner_report.json').read_text())['findings']
rulings = {
    'ADV-2025-0441': ('APPLIES', 'libhpack.a(hpack.o)'),
    'ADV-2025-0442': ('GC_DISCARDED', '.text._ZN5rotor11rotor_decodeEPKcm'),
    'ADV-2025-0443': ('NOT_LINKED', 'libmurmurx.a'),
    'ADV-2025-0444': ('PATCHED_IN_PLACE', 'fdddc2c246b3d56fbccfb57ae6c07a4eef463fae'),
    'ADV-2025-0445': ('APPLIES', '84079a935869f15a3dbf7bef5a6a1ba330073378'),
    'ADV-2025-0446': ('RUNTIME_BOUND', 'libcodecext.so'),
}
assert set(rulings) == {f['advisory_id'] for f in findings}
rows = []
for finding in findings:
    verdict, witness = rulings[finding['advisory_id']]
    rows.append({
        'advisory_id': finding['advisory_id'],
        'verdict': verdict,
        'witness': witness,
        'rejected_claim': finding['claim'] if verdict in {'NOT_LINKED', 'GC_DISCARDED', 'PATCHED_IN_PLACE'} else None,
    })
path = Path('/app/advisories.json')
path.write_text(json.dumps({'advisories': rows}, indent=2) + '\n')
result = json.loads(path.read_text())
assert set(result) == {'advisories'}
assert len(result['advisories']) == len(findings) == len({r['advisory_id'] for r in rows})
for finding, row in zip(findings, result['advisories']):
    assert set(row) == {'advisory_id', 'verdict', 'witness', 'rejected_claim'}
    assert row['advisory_id'] == finding['advisory_id']
    assert row['verdict'] in {'APPLIES', 'NOT_LINKED', 'GC_DISCARDED', 'PATCHED_IN_PLACE', 'RUNTIME_BOUND'}
    assert row['rejected_claim'] == (finding['claim'] if row['verdict'] in {'NOT_LINKED', 'GC_DISCARDED', 'PATCHED_IN_PLACE'} else None)
print(path.read_text())
print('Validated: exactly one entry per finding, permitted verdicts, and correct rejected_claim values.')
